package handler
import("encoding/json";"errors";"net/http";"strings";"github.com/alumasinde/budget254-paye-api/internal/department/model";repo "github.com/alumasinde/budget254-paye-api/internal/department/repository";"github.com/alumasinde/budget254-paye-api/internal/department/service";companyRepo "github.com/alumasinde/budget254-paye-api/internal/company/repository";"github.com/alumasinde/budget254-paye-api/internal/middleware";"github.com/alumasinde/budget254-paye-api/internal/response")
type Handler struct{Service service.Service}
func(h Handler) List(w http.ResponseWriter,r *http.Request){v,e:=h.Service.List(r.Context(),r.PathValue("company_id"),middleware.UserID(r.Context()));if e!=nil{writeError(w,r,e);return};response.JSON(w,http.StatusOK,map[string]any{"departments":v})}
func(h Handler) Create(w http.ResponseWriter,r *http.Request){var q model.CreateInput;if e:=decode(w,r,&q);e!=nil{fail(w,r,400,"INVALID_REQUEST","invalid request");return};v,e:=h.Service.Create(r.Context(),r.PathValue("company_id"),middleware.UserID(r.Context()),q);if e!=nil{writeError(w,r,e);return};response.JSON(w,http.StatusCreated,v)}
func(h Handler) Update(w http.ResponseWriter,r *http.Request){var q model.UpdateInput;if e:=decode(w,r,&q);e!=nil{fail(w,r,400,"INVALID_REQUEST","invalid request");return};v,e:=h.Service.Update(r.Context(),r.PathValue("company_id"),middleware.UserID(r.Context()),r.PathValue("department_id"),q);if e!=nil{writeError(w,r,e);return};response.JSON(w,http.StatusOK,v)}
func decode(w http.ResponseWriter,r *http.Request,v any)error{d:=json.NewDecoder(http.MaxBytesReader(w,r.Body,1<<20));d.DisallowUnknownFields();return d.Decode(v)}
func writeError(w http.ResponseWriter,r *http.Request,e error){switch{case errors.Is(e,companyRepo.ErrForbidden):fail(w,r,403,"FORBIDDEN","you do not have permission for this action");case errors.Is(e,repo.ErrNotFound):fail(w,r,404,"NOT_FOUND","requested resource was not found");case errors.Is(e,repo.ErrConflict):fail(w,r,409,"CONFLICT","a department with those details already exists");case errors.Is(e,repo.ErrInUse):fail(w,r,422,"DEPARTMENT_IN_USE",e.Error());default:m:=strings.TrimSpace(e.Error());if m==""{m="request could not be completed"};fail(w,r,422,"REQUEST_FAILED",m)}}
func fail(w http.ResponseWriter,r *http.Request,status int,code,msg string){response.Fail(w,status,code,msg,middleware.ID(r.Context()),nil)}